{
  "book_code": "JASHER",
  "verses": [
    {
      "chapter": 5,
      "verse": 19,
      "source_ref": "5:19",
      "text_ar": "ومَاتَ لامِخُ أَبُ نَوحٍ في تلك الأيام؛ ومع ذلك لم يَسْلُكْ بكلِ قلبِه سُبُلَ أَبِهِ، ومَاتَ في السنةِ مِئَةٍ وخَمسةٍ وتسعين من عُمْرِ نوح."
    },
    {
      "chapter": 5,
      "verse": 20,
      "source_ref": "5:20",
      "text_ar": "وكانَ عُمُرُ لامِخِ سَبْعَ مِئَةٍ وَسَبْعِينَ سَنَةً، فَمَاتَ."
    },
    {
      "chapter": 5,
      "verse": 21,
      "source_ref": "5:21",
      "text_ar": "وَماتَ جَمِيعُ بَنِي الإِنْسَانِ الّذين عَرَفُوا الرَّبَّ في تلك السَّنة قبل أن يُلْهِبَ الرَّبُّ عليهم شَرًّا؛ فَإِنَّ الرَّبَّ أَرَادَ أن يَمُوتُوا لِئلا يَرَوْا الشَّرَّ الّذي سَيَجْلِبهُ اللهُ على إِخْوَانِهِم وَأَقْرَابِهِم، كما صَرَّحَ بِذَلِكَ."
    },
    {
      "chapter": 5,
      "verse": 22,
      "source_ref": "5:22",
      "text_ar": "في ذلك الوقت، قال الرَّبُّ إلى نوح ومَثُوشَلَح: قُومَا وأعلَنَا لِبَنِي الإِنْسَانِ كُلَّ ما قُلْتُ لكُم في تلك الأيام، لَعَلَّهُمْ يَتَوَلَّوْنَ عَن سُبُلِهِم الشَّرِيرَةِ، فَأَتَابُ عَنْ الشَّرِّ ولا أُجْرِيهِ."
    },
    {
      "chapter": 5,
      "verse": 23,
      "source_ref": "5:23",
      "text_ar": "وَقَامَ نوح ومَثُوشَلَح، فَقَالا في آذان بَنِي الإِنْسَانِ كلَّ ما تَكَلَّمَ اللهُ عَنْهُمْ."
    }
  ]
}
